package com.gameaggregator.versionservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.versionservice.application.VersionService;import com.gameaggregator.versionservice.domain.GameVersion;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/versions") public class VersionController{final VersionService s;public VersionController(VersionService s){this.s=s;}@PostMapping ApiResponse<GameVersion> create(@Valid @RequestBody VersionDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<GameVersion>> list(@RequestParam(required=false)UUID gameId){return ApiResponse.success(s.list(gameId));}@GetMapping("/{id}")ApiResponse<GameVersion> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PutMapping("/{id}")ApiResponse<GameVersion> update(@PathVariable UUID id,@Valid @RequestBody VersionDtos.Update r){return ApiResponse.success(s.update(id,r));}@PatchMapping("/{id}/status")ApiResponse<GameVersion> status(@PathVariable UUID id,@Valid @RequestBody VersionDtos.Status r){return ApiResponse.success(s.status(id,r));}}